CREATE TYPE "PartnerOfferRevisionStatus" AS ENUM ('DRAFT','PENDING_APPROVAL','INTERNALLY_APPROVED','ISSUED','ACCEPTED','REJECTED','EXPIRED','WITHDRAWN','SUPERSEDED');
CREATE TABLE partner_offers (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),company_id UUID NOT NULL REFERENCES "Company"(id),offer_reference TEXT NOT NULL,created_by UUID NOT NULL REFERENCES "User"(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(company_id,offer_reference));
CREATE TABLE partner_offer_revisions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),partner_offer_id UUID NOT NULL REFERENCES partner_offers(id),revision_number INTEGER NOT NULL CHECK(revision_number>0),status "PartnerOfferRevisionStatus" NOT NULL DEFAULT 'DRAFT',currency_code TEXT NOT NULL,offer_total_excl_tax NUMERIC(18,6) NOT NULL,offer_tax_amount NUMERIC(18,6) NOT NULL DEFAULT 0,offer_total_incl_tax NUMERIC(18,6) NOT NULL,commercial_terms TEXT,payment_terms TEXT,delivery_terms TEXT,valid_until DATE,created_by UUID NOT NULL REFERENCES "User"(id),submitted_by UUID REFERENCES "User"(id),submitted_at TIMESTAMPTZ,approved_by UUID REFERENCES "User"(id),approved_at TIMESTAMPTZ,issued_by UUID REFERENCES "User"(id),issued_at TIMESTAMPTZ,accepted_by UUID REFERENCES "User"(id),accepted_at TIMESTAMPTZ,withdrawn_by UUID REFERENCES "User"(id),withdrawn_at TIMESTAMPTZ,withdrawal_reason TEXT,superseded_by_revision_id UUID REFERENCES partner_offer_revisions(id),correlation_id UUID,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(partner_offer_id,revision_number));
CREATE TABLE partner_offer_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),partner_offer_revision_id UUID NOT NULL REFERENCES partner_offer_revisions(id),line_number INTEGER NOT NULL,product_identity_id UUID NOT NULL REFERENCES product_identities(id),product_description TEXT NOT NULL,quantity NUMERIC(18,4) NOT NULL CHECK(quantity>0),unit_id UUID NOT NULL REFERENCES unit_definitions(id),unit_selling_price NUMERIC(18,6) NOT NULL,tax_treatment_code TEXT,tax_rate NUMERIC(9,6),tax_amount NUMERIC(18,6) NOT NULL DEFAULT 0,amount_excl_tax NUMERIC(18,6) NOT NULL,amount_incl_tax NUMERIC(18,6) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(partner_offer_revision_id,line_number));
CREATE TABLE offer_internal_bindings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),partner_offer_revision_id UUID NOT NULL UNIQUE REFERENCES partner_offer_revisions(id),pricing_revision_id UUID NOT NULL REFERENCES pricing_revisions(id),created_by UUID NOT NULL REFERENCES "User"(id),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE offer_approvals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),partner_offer_revision_id UUID NOT NULL UNIQUE REFERENCES partner_offer_revisions(id),decision TEXT NOT NULL CHECK(decision IN ('APPROVED','REJECTED')),actor_user_id UUID NOT NULL REFERENCES "User"(id),reason TEXT,correlation_id UUID,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX partner_offer_revisions_offer_idx ON partner_offer_revisions(partner_offer_id,revision_number);
CREATE INDEX partner_offers_company_idx ON partner_offers(company_id);
INSERT INTO "Permission"(id,code,description) VALUES
(gen_random_uuid(),'offer.create','Create and submit Partner Offers'),(gen_random_uuid(),'offer.read','Read internal Partner Offers'),(gen_random_uuid(),'offer.approve','Approve or reject Partner Offers'),(gen_random_uuid(),'offer.issue','Issue approved Partner Offers'),(gen_random_uuid(),'offer.withdraw','Withdraw issued Partner Offers'),(gen_random_uuid(),'offer.partner_read','Read own company Partner Offers'),(gen_random_uuid(),'offer.accept','Accept own company issued Partner Offers') ON CONFLICT(code) DO NOTHING;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['partner_offers','partner_offer_revisions','partner_offer_lines','offer_internal_bindings','offer_approvals'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t); EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t); EXECUTE format('REVOKE ALL ON TABLE public.%I FROM sco_runtime,sco_internal_executor',t); END LOOP; END $$;
CREATE FUNCTION public.prevent_offer_history_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' OR COALESCE(current_setting('app.offer_gateway',true),'')<>'true' THEN RAISE EXCEPTION 'OFFER_HISTORY_IMMUTABLE'; END IF; RETURN NEW; END $$;
CREATE TRIGGER partner_offer_revisions_immutable BEFORE UPDATE OR DELETE ON partner_offer_revisions FOR EACH ROW EXECUTE FUNCTION public.prevent_offer_history_mutation();
CREATE TRIGGER partner_offer_lines_immutable BEFORE UPDATE OR DELETE ON partner_offer_lines FOR EACH ROW EXECUTE FUNCTION public.prevent_offer_history_mutation();
CREATE TRIGGER offer_internal_bindings_immutable BEFORE UPDATE OR DELETE ON offer_internal_bindings FOR EACH ROW EXECUTE FUNCTION public.prevent_offer_history_mutation();
CREATE TRIGGER offer_approvals_immutable BEFORE UPDATE OR DELETE ON offer_approvals FOR EACH ROW EXECUTE FUNCTION public.prevent_offer_history_mutation();
CREATE FUNCTION public.partner_offer_capability(p_actor uuid,p_company uuid,p_code text) RETURNS boolean LANGUAGE sql SET search_path=pg_catalog,public AS $$ SELECT EXISTS(SELECT 1 FROM public."CompanyMembership" cm JOIN public."Company" c ON c.id=cm."companyId" AND c.type='PARTNER' AND c.status='ACTIVE' JOIN public."MembershipRole" mr ON mr.membership_id=cm.id JOIN public."RolePermission" rp ON rp.role_id=mr.role_id JOIN public."Permission" p ON p.id=rp.permission_id WHERE cm."userId"=p_actor AND cm."companyId"=p_company AND cm.status='ACTIVE' AND p.code=p_code) $$;
REVOKE ALL ON FUNCTION public.partner_offer_capability(uuid,uuid,text) FROM PUBLIC,sco_internal_executor;
CREATE FUNCTION public.internal_offer_create(p_actor uuid,p_offer uuid,p_pricing uuid,p_reference text,p_terms text,p_payment text,p_delivery text,p_correlation text) RETURNS TABLE(offer_id uuid,revision_id uuid) LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_offer uuid:=p_offer;v_revision uuid:=gen_random_uuid();v_company uuid;v_currency text;v_total numeric;v_tax numeric;v_previous uuid;v_number integer;BEGIN
IF NOT public.internal_has_capability(p_actor,'offer.create') THEN RAISE EXCEPTION 'OFFER_CREATE_FORBIDDEN'; END IF;
SELECT c.partner_company_id,r.selling_currency_code,r.selling_total INTO v_company,v_currency,v_total FROM public.pricing_revisions r JOIN public.pricing_cases c ON c.id=r.pricing_case_id WHERE r.id=p_pricing AND r.status='APPROVED'; IF v_company IS NULL THEN RAISE EXCEPTION 'OFFER_PRICING_NOT_APPROVED'; END IF;
IF v_offer IS NULL THEN v_offer:=gen_random_uuid();INSERT INTO public.partner_offers(id,company_id,offer_reference,created_by) VALUES(v_offer,v_company,p_reference,p_actor);v_number:=1; ELSE SELECT r.id,r.revision_number+1 INTO v_previous,v_number FROM public.partner_offer_revisions r JOIN public.partner_offers o ON o.id=r.partner_offer_id WHERE r.partner_offer_id=v_offer AND o.company_id=v_company ORDER BY r.revision_number DESC LIMIT 1 FOR UPDATE;IF v_previous IS NULL THEN RAISE EXCEPTION 'OFFER_NOT_AVAILABLE'; END IF; END IF;
SELECT COALESCE(sum(tax_amount),0) INTO v_tax FROM public.pricing_lines WHERE pricing_revision_id=p_pricing; PERFORM set_config('app.offer_gateway','true',true);
INSERT INTO public.partner_offer_revisions(id,partner_offer_id,revision_number,currency_code,offer_total_excl_tax,offer_tax_amount,offer_total_incl_tax,commercial_terms,payment_terms,delivery_terms,created_by,correlation_id) VALUES(v_revision,v_offer,v_number,v_currency,v_total,v_tax,v_total+v_tax,p_terms,p_payment,p_delivery,p_actor,NULLIF(p_correlation,'')::uuid);
INSERT INTO public.partner_offer_lines(partner_offer_revision_id,line_number,product_identity_id,product_description,quantity,unit_id,unit_selling_price,tax_treatment_code,tax_rate,tax_amount,amount_excl_tax,amount_incl_tax) SELECT v_revision,l.line_number,l.product_identity_id,concat_ws(' ',p.manufacturer,p.brand,p.model_reference),l.quantity,l.unit_id,l.unit_selling_price,l.tax_treatment_code,l.tax_rate,l.tax_amount,l.amount_excl_tax,l.amount_incl_tax FROM public.pricing_lines l JOIN public.product_identities p ON p.id=l.product_identity_id WHERE l.pricing_revision_id=p_pricing;
INSERT INTO public.offer_internal_bindings(partner_offer_revision_id,pricing_revision_id,created_by) VALUES(v_revision,p_pricing,p_actor); IF v_previous IS NOT NULL THEN UPDATE public.partner_offer_revisions SET status='SUPERSEDED',superseded_by_revision_id=v_revision WHERE id=v_previous; INSERT INTO public.audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,'SCO_INTERNAL','offer.superseded','PartnerOfferRevision',v_previous,'{}',NULLIF(p_correlation,'')::uuid); END IF;
INSERT INTO public.audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,'SCO_INTERNAL','offer.created','PartnerOffer',v_offer,jsonb_build_object('revisionId',v_revision),NULLIF(p_correlation,'')::uuid),(p_actor,'SCO_INTERNAL','offer.revision_created','PartnerOfferRevision',v_revision,jsonb_build_object('revisionNumber',v_number),NULLIF(p_correlation,'')::uuid); RETURN QUERY SELECT v_offer,v_revision; END $$;
CREATE FUNCTION public.internal_offer_submit(p_actor uuid,p_revision uuid,p_correlation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT public.internal_has_capability(p_actor,'offer.create') THEN RAISE EXCEPTION 'OFFER_CREATE_FORBIDDEN'; END IF;PERFORM set_config('app.offer_gateway','true',true);UPDATE public.partner_offer_revisions SET status='PENDING_APPROVAL',submitted_by=p_actor,submitted_at=now() WHERE id=p_revision AND status='DRAFT' AND created_by=p_actor;IF NOT FOUND THEN RAISE EXCEPTION 'OFFER_NOT_SUBMITTABLE'; END IF;INSERT INTO public.audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,'SCO_INTERNAL','offer.revision_submitted','PartnerOfferRevision',p_revision,'{}',NULLIF(p_correlation,'')::uuid);END $$;
CREATE FUNCTION public.internal_offer_decide(p_actor uuid,p_revision uuid,p_decision text,p_reason text,p_correlation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v_creator uuid; BEGIN IF p_decision NOT IN ('APPROVED','REJECTED') OR NOT public.internal_has_capability(p_actor,'offer.approve') THEN RAISE EXCEPTION 'OFFER_APPROVAL_FORBIDDEN'; END IF;SELECT created_by INTO v_creator FROM public.partner_offer_revisions WHERE id=p_revision AND status='PENDING_APPROVAL' FOR UPDATE;IF v_creator IS NULL THEN RAISE EXCEPTION 'OFFER_NOT_PENDING'; END IF;IF p_actor=v_creator THEN RAISE EXCEPTION 'OFFER_SEPARATION_OF_DUTIES_REQUIRED'; END IF;IF p_decision='REJECTED' AND btrim(COALESCE(p_reason,''))='' THEN RAISE EXCEPTION 'OFFER_REJECTION_REASON_REQUIRED'; END IF;PERFORM set_config('app.offer_gateway','true',true);UPDATE public.partner_offer_revisions SET status=CASE WHEN p_decision='APPROVED' THEN 'INTERNALLY_APPROVED'::"PartnerOfferRevisionStatus" ELSE 'REJECTED'::"PartnerOfferRevisionStatus" END,approved_by=p_actor,approved_at=now() WHERE id=p_revision;INSERT INTO public.offer_approvals(partner_offer_revision_id,decision,actor_user_id,reason,correlation_id) VALUES(p_revision,p_decision,p_actor,NULLIF(p_reason,''),NULLIF(p_correlation,'')::uuid);INSERT INTO public.audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,'SCO_INTERNAL',CASE WHEN p_decision='APPROVED' THEN 'offer.revision_approved' ELSE 'offer.revision_rejected' END,'PartnerOfferRevision',p_revision,jsonb_build_object('decision',p_decision),NULLIF(p_correlation,'')::uuid);END $$;
CREATE FUNCTION public.internal_offer_issue(p_actor uuid,p_revision uuid,p_valid date,p_correlation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT public.internal_has_capability(p_actor,'offer.issue') THEN RAISE EXCEPTION 'OFFER_ISSUE_FORBIDDEN'; END IF;IF p_valid IS NULL OR p_valid<current_date THEN RAISE EXCEPTION 'OFFER_VALID_UNTIL_REQUIRED'; END IF;IF EXISTS(SELECT 1 FROM public.offer_internal_bindings b JOIN public.pricing_cost_allocations a ON a.pricing_line_id IN(SELECT id FROM public.pricing_lines WHERE pricing_revision_id=b.pricing_revision_id) JOIN public.approved_purchase_cost_snapshots s ON s.id=a.approved_purchase_cost_snapshot_id JOIN public.supplier_quote_revisions q ON q.id=s.supplier_quote_revision_id WHERE b.partner_offer_revision_id=p_revision AND (s.status<>'APPROVED' OR s.approved_quantity<a.allocated_quantity OR q.valid_until IS NULL OR q.valid_until<p_valid)) THEN RAISE EXCEPTION 'OFFER_VALIDITY_NOT_SUPPORTED'; END IF;PERFORM set_config('app.offer_gateway','true',true);UPDATE public.partner_offer_revisions SET status='ISSUED',valid_until=p_valid,issued_by=p_actor,issued_at=now() WHERE id=p_revision AND status='INTERNALLY_APPROVED';IF NOT FOUND THEN RAISE EXCEPTION 'OFFER_NOT_ISSUABLE'; END IF;INSERT INTO public.audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,'SCO_INTERNAL','offer.issued','PartnerOfferRevision',p_revision,'{}',NULLIF(p_correlation,'')::uuid);END $$;
CREATE FUNCTION public.internal_offer_withdraw(p_actor uuid,p_revision uuid,p_reason text,p_correlation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF NOT public.internal_has_capability(p_actor,'offer.withdraw') THEN RAISE EXCEPTION 'OFFER_WITHDRAW_FORBIDDEN'; END IF;IF btrim(COALESCE(p_reason,''))='' THEN RAISE EXCEPTION 'OFFER_WITHDRAWAL_REASON_REQUIRED'; END IF;PERFORM set_config('app.offer_gateway','true',true);UPDATE public.partner_offer_revisions SET status='WITHDRAWN',withdrawn_by=p_actor,withdrawn_at=now(),withdrawal_reason=p_reason WHERE id=p_revision AND status='ISSUED';IF NOT FOUND THEN RAISE EXCEPTION 'OFFER_NOT_WITHDRAWABLE'; END IF;INSERT INTO public.audit_logs(actor_user_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,'SCO_INTERNAL','offer.withdrawn','PartnerOfferRevision',p_revision,'{}',NULLIF(p_correlation,'')::uuid);END $$;
CREATE FUNCTION public.internal_offer_binding_get(p_actor uuid,p_revision uuid) RETURNS TABLE(pricing_revision_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ SELECT b.pricing_revision_id FROM public.offer_internal_bindings b WHERE b.partner_offer_revision_id=p_revision AND public.internal_has_capability(p_actor,'offer.read') $$;
CREATE FUNCTION public.partner_offer_projection(p_actor uuid,p_company uuid,p_revision uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE v jsonb;BEGIN IF current_setting('app.tenant_id',true) IS DISTINCT FROM p_company::text OR NOT public.partner_offer_capability(p_actor,p_company,'offer.partner_read') THEN RETURN NULL;END IF;SELECT jsonb_build_object('offerId',o.id,'offerReference',o.offer_reference,'revisionId',r.id,'revisionNumber',r.revision_number,'status',CASE WHEN r.status='ISSUED' AND r.valid_until<current_date THEN 'EXPIRED' ELSE r.status END,'currency',r.currency_code,'validUntil',r.valid_until,'totalExclTax',r.offer_total_excl_tax,'taxAmount',r.offer_tax_amount,'totalInclTax',r.offer_total_incl_tax,'commercialTerms',r.commercial_terms,'paymentTerms',r.payment_terms,'deliveryTerms',r.delivery_terms,'lines',COALESCE((SELECT jsonb_agg(jsonb_build_object('productIdentityId',l.product_identity_id,'description',l.product_description,'quantity',l.quantity,'unitId',l.unit_id,'unitSellingPrice',l.unit_selling_price,'taxTreatment',l.tax_treatment_code,'taxAmount',l.tax_amount,'totalInclTax',l.amount_incl_tax) ORDER BY l.line_number) FROM public.partner_offer_lines l WHERE l.partner_offer_revision_id=r.id),'[]'::jsonb)) INTO v FROM public.partner_offer_revisions r JOIN public.partner_offers o ON o.id=r.partner_offer_id WHERE r.id=p_revision AND o.company_id=p_company;RETURN v;END $$;
CREATE FUNCTION public.partner_offer_accept(p_actor uuid,p_company uuid,p_offer uuid,p_revision uuid,p_correlation text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ BEGIN IF current_setting('app.tenant_id',true) IS DISTINCT FROM p_company::text OR NOT public.partner_offer_capability(p_actor,p_company,'offer.accept') THEN RAISE EXCEPTION 'OFFER_NOT_AVAILABLE'; END IF;PERFORM set_config('app.offer_gateway','true',true);UPDATE public.partner_offer_revisions r SET status='ACCEPTED',accepted_by=p_actor,accepted_at=now() FROM public.partner_offers o WHERE r.id=p_revision AND r.partner_offer_id=p_offer AND o.id=p_offer AND o.company_id=p_company AND r.status='ISSUED' AND r.valid_until>=current_date;IF NOT FOUND THEN RAISE EXCEPTION 'OFFER_NOT_AVAILABLE'; END IF;INSERT INTO public.audit_logs(actor_user_id,company_id,scope,action,entity_type,entity_id,metadata,correlation_id) VALUES(p_actor,p_company,'TENANT','offer.accepted','PartnerOfferRevision',p_revision,jsonb_build_object('offerId',p_offer),NULLIF(p_correlation,'')::uuid);RETURN true;END $$;
REVOKE ALL ON FUNCTION public.internal_offer_create(uuid,uuid,uuid,text,text,text,text,text),public.internal_offer_submit(uuid,uuid,text),public.internal_offer_decide(uuid,uuid,text,text,text),public.internal_offer_issue(uuid,uuid,date,text),public.internal_offer_withdraw(uuid,uuid,text,text),public.internal_offer_binding_get(uuid,uuid),public.partner_offer_projection(uuid,uuid,uuid),public.partner_offer_accept(uuid,uuid,uuid,uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.internal_offer_create(uuid,uuid,uuid,text,text,text,text,text),public.internal_offer_submit(uuid,uuid,text),public.internal_offer_decide(uuid,uuid,text,text,text),public.internal_offer_issue(uuid,uuid,date,text),public.internal_offer_withdraw(uuid,uuid,text,text),public.internal_offer_binding_get(uuid,uuid) TO sco_internal_executor;
GRANT EXECUTE ON FUNCTION public.partner_offer_projection(uuid,uuid,uuid),public.partner_offer_accept(uuid,uuid,uuid,uuid,text) TO sco_runtime;
